package com.jnapanam.sportszone.promotion.controller;import com.jnapanam.sportszone.promotion.dto.*;import com.jnapanam.sportszone.promotion.service.PromotionService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/admin/promotions")@PreAuthorize("hasAnyRole('SUPER_ADMIN','ADMIN')")public class AdminPromotionController{private final PromotionService service;public AdminPromotionController(PromotionService s){service=s;}@GetMapping public List<PromotionResponse>all(){return service.all();}@PostMapping@ResponseStatus(HttpStatus.CREATED)public PromotionResponse create(@Valid@RequestBody PromotionRequest r){return service.create(r);}@PutMapping("/{id}")public PromotionResponse update(@PathVariable UUID id,@Valid@RequestBody PromotionRequest r){return service.update(id,r);}}
